-- Nutrition three-section proof only. Existing explore_content records are never modified.
begin;
create table if not exists public.explore_nutrition_content (
 content_id text primary key,
 parent_id text references public.explore_nutrition_content(content_id),
 kind text not null check (kind in ('HUB','SECTION')),
 sort_order integer not null check (sort_order >= 0),
 title text not null check (length(trim(title))>0),
 educational_state text check (educational_state in ('NATURALLY_GF','CHECK_DETAILS','CONTAINS_GLUTEN')),
 body jsonb not null check (jsonb_typeof(body)='object'),
 source_metadata jsonb not null check (jsonb_typeof(source_metadata)='object'),
 review_status text not null default 'DRAFT' check (review_status in ('DRAFT','IN_REVIEW','APPROVED','ARCHIVED')),
 active boolean not null default false,
 check ((kind='HUB' and parent_id is null and educational_state is null) or (kind='SECTION' and parent_id is not null))
);
alter table public.explore_nutrition_content enable row level security;
revoke all on public.explore_nutrition_content from anon,authenticated;
grant select on public.explore_nutrition_content to anon,authenticated;
do $policy$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='explore_nutrition_content' and policyname='Read approved nutrition education') then
 execute 'create policy "Read approved nutrition education" on public.explore_nutrition_content for select to anon,authenticated using (active and review_status=''APPROVED'')';
 end if;
end $policy$;
comment on table public.explore_nutrition_content is 'Plan My C-Day in-app nutrition education. Separate from external expert resources and Community. No completion/XP behavior.';
lock table public.explore_nutrition_content in share row exclusive mode;
do $import$
declare wanted jsonb; incoming public.explore_nutrition_content%rowtype; current_row public.explore_nutrition_content%rowtype;
begin
for wanted in select value from jsonb_array_elements($records$[{"parent_id": null, "kind": "HUB", "sort_order": 0, "title": "What can I eat?", "educational_state": null, "body": {"subtitle": "A gluten-free diet can include a lot more than packaged GF substitutes. Start with foods that are naturally gluten-free, learn what needs checking, and know the ingredients that contain gluten."}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app."}, "review_status": "APPROVED", "active": true, "content_id": "NUT_HOME"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 1, "title": "Naturally GF", "educational_state": "NATURALLY_GF", "body": {"intro": "These foods are naturally gluten-free when they are plain and have not picked up gluten through added ingredients or cross-contact.", "items": ["Fruit and vegetables", "Plain meat, poultry, fish, and eggs", "Milk and many plain dairy foods", "Beans, lentils, nuts, and seeds", "Rice, potatoes, corn, quinoa, buckwheat, amaranth, millet, sorghum, tapioca, teff, and other gluten-free grains/starches"], "safety_note": "Naturally gluten-free does not mean every prepared version is automatically appropriate. Sauces, coatings, seasonings, preparation, and cross-contact can change the answer.", "qualifier": null, "uncertainty_label": null, "visual_asset_id": "VIS_NUT_001"}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "A. NATURALLY GF — Start Here", "original_section_lines": ["Teen-facing copy: “These foods are naturally gluten-free when they are plain and have not picked up gluten through added ingredients or cross-contact.”", "Fruit and vegetables", "Plain meat, poultry, fish, and eggs", "Milk and many plain dairy foods", "Beans, lentils, nuts, and seeds", "Rice, potatoes, corn, quinoa, buckwheat, amaranth, millet, sorghum, tapioca, teff, and other gluten-free grains/starches", "Safety line: Naturally gluten-free does not mean every prepared version is automatically appropriate. Sauces, coatings, seasonings, preparation, and cross-contact can change the answer."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_001"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 2, "title": "Check the Details", "educational_state": "CHECK_DETAILS", "body": {"intro": "These foods are not automatically a yes or a no. Check the label, ingredients, preparation, or source.", "items": ["Oats — use oats labeled gluten-free and follow your celiac clinician/dietitian’s individualized advice.", "Soups, sauces, gravies, marinades, and seasoning blends.", "Processed meats, meat substitutes, and flavored proteins.", "Fries and other fried foods — check ingredients and whether shared fryer oil/equipment is used.", "Flavored yogurt, ice cream, smoothies, and other foods with mix-ins.", "Prepared fruits or vegetables with sauces, coatings, breading, or toppings.", "Grains, seeds, and legumes that may have cross-contact during processing."], "safety_note": null, "qualifier": null, "uncertainty_label": "Needs More Information", "visual_asset_id": "VIS_NUT_003"}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "B. CHECK THE DETAILS", "original_section_lines": ["Teen-facing copy: “These foods are not automatically a yes or a no. Check the label, ingredients, preparation, or source.”", "Oats — use oats labeled gluten-free and follow your celiac clinician/dietitian’s individualized advice.", "Soups, sauces, gravies, marinades, and seasoning blends.", "Processed meats, meat substitutes, and flavored proteins.", "Fries and other fried foods — check ingredients and whether shared fryer oil/equipment is used.", "Flavored yogurt, ice cream, smoothies, and other foods with mix-ins.", "Prepared fruits or vegetables with sauces, coatings, breading, or toppings.", "Grains, seeds, and legumes that may have cross-contact during processing."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_002"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 3, "title": "Contains Gluten", "educational_state": "CONTAINS_GLUTEN", "body": {"intro": null, "items": ["Wheat and wheat varieties such as durum, semolina, spelt, emmer/farro, einkorn, and kamut.", "Barley and barley-derived malt ingredients.", "Rye.", "Triticale.", "Traditional breads, pastas, baked goods, and breaded foods made with gluten-containing grains.", "Foods containing gluten ingredients unless they have been specially formulated/processed and meet applicable gluten-free labeling requirements."], "safety_note": null, "qualifier": "Unless Specifically Made to Meet GF Requirements", "uncertainty_label": null, "visual_asset_id": "VIS_NUT_004"}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "C. CONTAINS GLUTEN — Unless Specifically Made to Meet GF Requirements", "original_section_lines": ["Wheat and wheat varieties such as durum, semolina, spelt, emmer/farro, einkorn, and kamut.", "Barley and barley-derived malt ingredients.", "Rye.", "Triticale.", "Traditional breads, pastas, baked goods, and breaded foods made with gluten-containing grains.", "Foods containing gluten ingredients unless they have been specially formulated/processed and meet applicable gluten-free labeling requirements."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_003"}]$records$::jsonb) loop
 select * into incoming from jsonb_populate_record(null::public.explore_nutrition_content,wanted);
 select * into current_row from public.explore_nutrition_content where content_id=incoming.content_id for update;
 if found then
  if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then raise exception 'Nutrition record differs: %. No changes made.',incoming.content_id; end if;
 else
 insert into public.explore_nutrition_content (parent_id,kind,sort_order,title,educational_state,body,source_metadata,review_status,active,content_id) values (incoming.parent_id,incoming.kind,incoming.sort_order,incoming.title,incoming.educational_state,incoming.body,incoming.source_metadata,incoming.review_status,incoming.active,incoming.content_id);
 end if;
end loop;
end $import$;
commit;
